// Sole owner of the "Activities" tab. Same contract as write-restaurants-v2.mjs:
// this file is the source of truth, the sheet is the output, and nothing else
// writes to that tab.
//
// WHY A SEPARATE TAB RATHER THAN MORE ROWS IN Restaurants v2
// The restaurant schema is 64 columns built around food - cuisine, specialities,
// price band, signature dish, deals, dietary, booking lead. Almost none of it
// applies to axe throwing. Mixing them would also break every count and filter
// the site depends on: "615 rows" would stop meaning "restaurants", and the
// closed vocabularies would have to accept values that make no sense for either
// type.
//
// The LOCATION AND PROVENANCE SPINE is deliberately identical, so
// scripts/enrich.mjs works on this tab unchanged - Places for the address,
// postcodes.io for coordinates (free, and unlike Google's, storable), then walk
// times. Do not rename those columns.
//
//   node scripts/write-activities.mjs
//
import fs from "node:fs";
import { writeTab } from "./sheets.mjs";

const TODAY = new Date().toISOString().slice(0, 10);

const COLUMNS = [
  // --- shared spine: identical names to Restaurants v2 so enrich.mjs works ---
  { key: "slug", head: "Slug" },
  { key: "name", head: "Name" },
  { key: "status", head: "Status" },
  { key: "statusChecked", head: "Status Checked" },
  // --- what it actually is ---
  { key: "activityType", head: "Activity Type" },
  { key: "style", head: "Style" },
  { key: "venueContext", head: "Venue Context" },
  { key: "chainType", head: "Chain Type" },
  { key: "ownerGroup", head: "Owner Group" },
  // --- where ---
  { key: "hood", head: "Neighbourhood" },
  { key: "borough", head: "Borough" },
  { key: "areaGuide", head: "Area Guide" },
  // WHERE THIS ROW IS ALLOWED TO APPEAR ON ITS AREA GUIDE.
  //
  //   (blank)  normal - listed in the guide's auto "Things to do" section.
  //   prose    the guide already covers it in its own hand-written text, so
  //            the auto section SKIPS it. The row still exists everywhere else:
  //            /things-to-do, the activity filters, the maps and search.
  //
  // WHY. A guide's "Top sights and activities" list is hand-curated, and the
  // Things to do section is generated from this sheet. When both name the same
  // venue the page prints it twice - which is what Neal's Yard, Seven Dials
  // Market and the Guinness brewery all did. Deleting the row is the wrong fix,
  // because a Londoner browsing /things-to-do should still find Tower of London
  // even though the City guide already has a paragraph on it.
  //
  // So the row is the record and this field decides the DISPLAY. Nothing about
  // a venue's importance is encoded here - only whether one page would repeat.
  { key: "guidePlacement", head: "Guide Placement" },
  { key: "zone", head: "Zone" },
  { key: "district", head: "District" },
  { key: "address", head: "Address" },
  { key: "postcode", head: "Postcode" },
  { key: "lat", head: "Lat" },
  { key: "lng", head: "Lng" },
  { key: "placeId", head: "Place ID" },
  { key: "station", head: "Nearest Station" },
  { key: "walkMin", head: "Walk Min" },
  // --- planning a visit. These are the columns guides routinely omit. ---
  { key: "agePolicy", head: "Age Policy" },
  { key: "seasonal", head: "Seasonal" },
  // Which days the venue actually trades AS A MARKET. Deliberately blank for
  // the shopping streets and malls that also carry activityType
  // "market-visit" (Carnaby Street, the King's Road, Battersea Power Station):
  // they are places to shop, not markets with trading days, and listing them
  // on a "markets by day" page would be wrong. Presence of this field is what
  // qualifies a row for /markets - so the distinction lives in the data,
  // not in the page.
  //
  // Values are human-readable rather than a fixed vocabulary ("Saturday",
  // "Thu-Sun", "Daily") because that is what a reader needs to see; the page
  // parses them into day buckets for grouping.
  { key: "marketDays", head: "Market Days" },
  // What you can actually DO with the food there, which is the question a
  // hungry visitor is really asking and the one "market" does not answer.
  // Columbia Road sells flowers; Billingsgate sells raw fish at 4am; Maltby
  // Street sells you lunch. All three are "markets".
  //
  //   hot-food     you can eat a meal there, now
  //   provisions   ingredients and produce to take away
  //   both         genuinely both, like Borough or Broadway Market
  //   (blank)      not a food market - flowers, antiques, a shopping street
  //
  // Blank is meaningful rather than missing: it is how the flower and antique
  // markets, and the shopping streets that share activityType "market-visit",
  // stay off a page about eating.
  { key: "foodOffer", head: "Food Offer" },
  { key: "duration", head: "Typical Duration" },
  { key: "groupSize", head: "Group Size" },
  { key: "pricePerPerson", head: "Price Per Person" },
  { key: "bookingRequired", head: "Booking Required" },
  { key: "indoorOutdoor", head: "Indoor / Outdoor" },
  { key: "stepFree", head: "Step-Free" },
  { key: "servesFood", head: "Serves Food" },
  { key: "servesAlcohol", head: "Serves Alcohol" },
  // --- editorial ---
  { key: "whyGo", head: "Why Go" },
  { key: "angle", head: "Angle" },
  { key: "opSummary", head: "Operational Summary" },
  { key: "goodFor", head: "Good For" },
  { key: "lists", head: "Lists" },
  // --- provenance ---
  { key: "website", head: "Website" },
  { key: "bookingUrl", head: "Booking URL" },
  { key: "source", head: "Source" },
  { key: "firstSeen", head: "First Seen" },
  { key: "lastChecked", head: "Last Checked" },
  { key: "verified", head: "Verified" },
];

// Closed lists. Build fails on anything outside them, same as the restaurant
// sheet - the point is that a typo cannot quietly create a new category.
const VOCAB = {
  activityType: [
    "darts", "shuffleboard", "mini-golf", "karting", "axe-throwing", "bowling",
    "arcade", "escape-room", "immersive-theatre", "immersive-game", "climbing",
    "cinema", "ice-rink", "karaoke", "ping-pong", "pool", "cricket",
    "clay-shooting", "trampoline", "soft-play", "roller-skating", "laser-tag",
    "vr", "boating", "swimming", "gallery-experience",
    // A whole indoor amusement park is not an arcade. Filing Babylon Park -
    // three storeys, bumper cars, a carousel and London's only indoor
    // rollercoaster - under "arcade" would have described the smallest part
    // of it and buried the thing families are actually searching for.
    "theme-park",
    // Added after the PROPER consensus pass. The first seed was hand-assembled
    // and had no category for a public garden, a market or a cable car - which
    // is precisely why it missed the free things, and the free things are often
    // the best answer to "what else is there here".
    "golf", "roof-garden", "park", "market-visit", "cable-car", "masterclass",
    // Shoreditch pass. Activity guides cover a much wider spread of venue types
    // than restaurant guides cover of cuisines - a museum, a record shop and a
    // ball pit all appear on the same list.
    "museum", "historic-house", "music-venue", "record-shop", "street-art",
    "bingo", "ball-pit",
    // All-guides pass. Conventional theatres are deliberately absent - they are
    // the sister site's subject, not this one's. Everything here is a thing you
    // DO rather than a thing you sit and watch.
    "aquarium", "observation-wheel", "skate-park", "bookshop", "planetarium",
    "zoo", "viewpoint", "spa", "walking-tour", "farm", "lido", "garden",
    "sport-stadium", "distillery-tour", "brewery-tour", "food-tour",
    // THEATRE RULE, and it is the cinema rule again: a theatre earns a row only
    // when the ROOM is the reason to go - a puppet theatre on a canal barge, a
    // surviving Victorian music hall. The performance programme itself belongs
    // to the sister theatre site, so a conventional playhouse gets no row here
    // however good the show is.
    "theatre", "cycling", "abseiling", "cemetery",
    // Competitive-socialising pass. The all-guides pass covered breadth and
    // missed this category almost entirely - it returned parks, museums and
    // markets, because that is what "things to do in {area}" lists are made of.
    // Darts, bowling and axe throwing live on a different population of lists
    // ("best activity bars", "competitive socialising"), exactly the way ramen
    // and omakase needed their own searches inside Japanese.
    "racing-sim", "board-games",
    // Circus skills taught to the public - a flying trapeze school, a static
    // trapeze or aerial-hoop class. NOT a circus show you sit and watch, which
    // is a performance and belongs to the sister theatre site under the same
    // rule that keeps playhouses out of this tab.
    "circus",
  ],
  // "18+ after 6pm" is the single most useful fact for a family and almost
  // nobody publishes it clearly. Fairgame is 18+ at ALL times and reads like a
  // family arcade, which is exactly the trap this column exists to close.
  agePolicy: ["all-ages", "family-friendly", "over-18", "over-18-evenings", "over-16", "adults-only"],
  seasonal: ["", "winter-only", "summer-only", "seasonal"],
  bookingRequired: ["required", "recommended", "walk-in"],
  indoorOutdoor: ["indoor", "outdoor", "both"],
  chainType: ["independent", "mini-chain", "chain"],
  angle: ["room", "access", "value", "contrast", "origin", "dish", "chef"],
  stepFree: ["", "yes", "no", "partial"],
  servesFood: ["", "yes", "no"],
  servesAlcohol: ["", "yes", "no"],
};

