// ------------------------------------------------- merge geocoding cache ---
// data/geo-cache.json is produced by scripts/geocode-listings.mjs. Merging
// here rather than writing to the sheet directly means this script stays the
// single owner of the tab, and the Places lookups survive every rebuild.
// Hand-written values win, matching write-restaurants-v2.mjs's enrichment merge.
const GEO_PATH = "data/geo-cache.json";
const GEO_MAP = { postcode: "postcode", lat: "lat", lng: "lng", placeId: "placeId" };
let geocoded = 0;
if (fs.existsSync(GEO_PATH)) {
  const cache = JSON.parse(fs.readFileSync(GEO_PATH, "utf8"));
  for (const r of ROWS) {
    const e = cache[`activities:${r.slug}`];
    if (!e) continue;
    for (const [col, key] of Object.entries(GEO_MAP)) {
      const v = e[key];
      if (v === undefined || v === "" || v === null) continue;
      if (String(r[col] ?? "").trim() !== "") continue;
      r[col] = String(v);
      geocoded++;
    }
  }
}

// --------------------------------------------------------------- validate ---
const errors = [];
for (const r of ROWS) {
  for (const [field, allowed] of Object.entries(VOCAB)) {
    const v = String(r[field] ?? "");
    if (v === "" && allowed.includes("")) continue;
    if (v === "" && !allowed.includes("")) continue;      // blank is "not established"
    for (const part of v.split(",").map((x) => x.trim()).filter(Boolean))
      if (!allowed.includes(part))
        errors.push(`${r.slug}: ${field} = "${part}" is not in [${allowed.filter(Boolean).join(", ")}]`);
  }
  if (r.hood && !HOODS[r.hood]) errors.push(`${r.slug}: neighbourhood "${r.hood}" is not in HOODS`);
}
if (errors.length) {
  console.error(`${errors.length} vocabulary error(s):`);
  for (const e of errors) console.error("  " + e);
  process.exit(1);
}
for (const r of ROWS) {
  const h = HOODS[r.hood];
  if (h) { r.zone ??= h.zone; r.district ??= h.district; }
}

const seen = new Set();
for (const r of ROWS) {
  if (seen.has(r.slug)) { console.error(`duplicate slug: ${r.slug}`); process.exit(1); }
  seen.add(r.slug);
}

const header = COLUMNS.map((c) => c.head);
const rows = ROWS.map((r) => COLUMNS.map((c) => String(r[c.key] ?? "")));

// --dry-run validates and reports without touching the sheet. Added during the
// all-guides pass, where the rows were written in batches and running the real
// write after every batch would have rewritten the whole tab a dozen times.
const dryRun = process.argv.includes("--dry-run");
if (!dryRun) await writeTab("Activities", header, rows);
else console.log("DRY RUN - nothing written to the sheet");

console.log(`wrote ${rows.length} rows x ${header.length} columns to "Activities"`);
const byType = {};
for (const r of ROWS) byType[r.activityType] = (byType[r.activityType] ?? 0) + 1;
console.log("  types: " + Object.entries(byType).map(([k, v]) => `${k} ${v}`).join(", "));
const flagged = ROWS.filter((r) => /NEEDS VERIFYING/.test(r.source + r.opSummary));
console.log(`  ${flagged.length} row(s) carry a NEEDS VERIFYING note: ${flagged.map((r) => r.name).join(", ")}`);
console.log(`  age policies: ${[...new Set(ROWS.map((r) => r.agePolicy))].join(", ")}`);
const withCoords = ROWS.filter((r) => r.lat).length;
console.log(`  ${withCoords}/${ROWS.length} rows have coordinates (${geocoded} field(s) merged from data/geo-cache.json this run)`);
